    var _p2=parseJsonLoose('Вот ответ: {"x":2} готово');
    if(!_p2||_p2.x!==2) __r.push("КРЭШ parseJsonLoose: не вытащил JSON из текста вокруг");
    var _thr=function(s){ try{ parseJsonLoose(s); return null; }catch(e){ return e.message||"err"; } };
    if(_thr('совсем не json')===null) __r.push("КРЭШ parseJsonLoose: не бросил на не-JSON");
    if(_thr('')===null) __r.push("КРЭШ parseJsonLoose: не бросил на пустой ответ");
