  var _pnP=S.prog, _pnBusy=S.slotBusy, _pnChg=S.slotChg, _pnDow=dowOf(td());
  var _pnFix={cfg:{equip:"gym",exp:"mid",goal:"hyper"},split:"т",plan:[{n:"Т",dow:_pnDow,ex:[
    {n:"Тяга верхнего блока",sets:3,lo:10,hi:15,main:false}]}]};
  S.prog=_pnFix; S.slotBusy={}; S.slotChg={};
